def execute(code,mask,bookmark,dirty,desired,prefix,variant):
 u=Uc(UC_ARCH_X86,UC_MODE_32)
 for a,n in [(0xa05000,0x3000),(OBJECT,0x4000),(STACK,0x10000),(STOP,4096),(0x1396000,4096)]:u.mem_map(a,n)
 def put(a,v):u.mem_write(a,struct.pack('<I',v&0xffffffff))
 u.mem_write(ENTRY,bytes(code));u.mem_write(OBJECT,b'\xa5'*0x3a3c)
 values={a:(0x80800000+i if variant else VALUES[i]) for i,a in enumerate(ADDRESSES)}
 for a,v in values.items():put(a,v)
 final=[0x55555555]*231
 for off,v in OPERATIONS:final[(off-0x2818)//20]=values.get(v,v)
 current=[0,1,0x80000000][mask];put(OBJECT+0x2808,[0,1,795][prefix]);put(OBJECT+0x280c,[0,1,31][prefix]);put(OBJECT+0x2814,current)
 for i in range(231):
  state=OBJECT+0x2818+i*20;put(state+4,final[i] if desired==1 or (desired==2 and i%2) else 0x55555555)
  put(state+8,0 if bookmark==0 else 0xffffffff if bookmark==1 else current if i%2 else 0);u.mem_write(state+16,bytes([int(dirty==1 or (dirty==2 and i%2))]))
 sp=STACK+0x8000;put(sp,STOP);u.reg_write(UC_X86_REG_ESP,sp);u.reg_write(UC_X86_REG_ECX,OBJECT)
 preserved=[UC_X86_REG_EBX,UC_X86_REG_EBP,UC_X86_REG_ESI,UC_X86_REG_EDI]
 for i,r in enumerate(preserved):u.reg_write(r,0xabcd0000+i)
 u.emu_start(ENTRY,STOP,count=50000)
 assert u.reg_read(UC_X86_REG_EIP)==STOP and u.reg_read(UC_X86_REG_ESP)==sp+4
 for i,r in enumerate(preserved):assert u.reg_read(r)==0xabcd0000+i
 for a,v in values.items():assert bytes(u.mem_read(a,4))==struct.pack('<I',v)
 return bytes(u.mem_read(OBJECT,0x3a3c))
